#include <vector>
#include "stack.h"
#include "queue.h"

//==========================================
// HISTORY MODULE (HOA 4 stacks, HOA 5 queues)
//
// BrowseHistory : Back / Forward between the game pages that were opened, like a web browser.
//                 Two stacks: "back" (pages behind us) and "forward" (pages we went back from).
//                 Opening a NEW page clears the forward stack.
// RecentlyViewed: the last few games opened, newest first, a circular queue that drops the oldest.
// CartUndo      : remembers the last cart actions so they can be undone, a linked stack.
//
// These live only in memory for the running session (nothing is saved to a file).
// Used by store.h (doViewGame) and screens_discover.h (history screens, cart undo).
//==========================================

class BrowseHistory {
private:
    ArrayStack<int> backStack;
    ArrayStack<int> forwardStack;
    int currentId;                  // 0 = no page opened yet

public:
//--- BrowseHistory::BrowseHistory -----------------------------------------------------------------
// What    : Creates a history with no page opened yet.
// Used by : tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    BrowseHistory() : currentId(0) {}

//--- BrowseHistory::current -----------------------------------------------------------------------
// What    : The game page that is open now.
// Returns : the game id, 0 when none
// Used by : doHistory (screens.h), tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    int current() const { return currentId; }
//--- BrowseHistory::canGoBack ---------------------------------------------------------------------
// What    : Tells if the back stack holds a page.
// Returns : true when Back is possible
// Used by : doHistory (screens.h)
//--------------------------------------------------------------------------------------------------
    bool canGoBack() const { return !backStack.empty(); }
//--- BrowseHistory::canGoForward ------------------------------------------------------------------
// What    : Tells if the forward stack holds a page.
// Returns : true when Forward is possible
// Used by : doHistory (screens.h), tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    bool canGoForward() const { return !forwardStack.empty(); }

    // a game page was opened by the user
//--- BrowseHistory::visit -------------------------------------------------------------------------
// What    : A page was opened by the user: the current page goes on the back stack and the forward
//           stack is cleared.
// Used by : doViewGame (store.h), tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    void visit(int gameId) {
        if (gameId == currentId) return;
        if (currentId != 0) backStack.push(currentId);
        currentId = gameId;
        forwardStack.clear();
    }

    // returns the game id to show, or 0 when there is nothing behind
//--- BrowseHistory::goBack ------------------------------------------------------------------------
// What    : Pops the back stack and pushes the current page on the forward stack.
// Returns : the game id to show, 0 when nothing is behind
// Used by : doHistory (screens.h), tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    int goBack() {
        int previous;
        if (!backStack.pop(previous)) return 0;
        forwardStack.push(currentId);
        currentId = previous;
        return currentId;
    }

    // returns the game id to show, or 0 when there is nothing ahead
//--- BrowseHistory::goForward ---------------------------------------------------------------------
// What    : Pops the forward stack and pushes the current page on the back stack.
// Returns : the game id to show, 0 when nothing is ahead
// Used by : doHistory (screens.h), tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    int goForward() {
        int next;
        if (!forwardStack.pop(next)) return 0;
        backStack.push(currentId);
        currentId = next;
        return currentId;
    }

    // the pages behind the current one, oldest first
//--- BrowseHistory::backList ----------------------------------------------------------------------
// What    : The pages behind the current one, oldest first.
// Returns : the game ids
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    std::vector<int> backList() const {
        std::vector<int> out;
        int id;
        for (int i = 0; backStack.at(i, id); i++) out.push_back(id);
        return out;
    }
};

class RecentlyViewed {
private:
    CircularQueue<int> items;

public:
//--- RecentlyViewed::RecentlyViewed ---------------------------------------------------------------
// What    : Creates the list with room for the given number of games.
// Used by : tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    explicit RecentlyViewed(int size = 5) : items(size) {}

    // the game moves to the newest place, an earlier copy of it is removed first
//--- RecentlyViewed::add --------------------------------------------------------------------------
// What    : Puts a game at the newest place. An earlier copy of the same game is removed first, and
//           the oldest game falls out when the circular queue is full.
// Used by : doViewGame (store.h), tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    void add(int gameId) {
        CircularQueue<int> rebuilt(items.maxSize());
        int id;
        for (int i = 0; items.at(i, id); i++) {
            if (id != gameId) rebuilt.enqueue(id);
        }
        rebuilt.enqueueOverwrite(gameId);
        items = rebuilt;
    }

    // newest first
//--- RecentlyViewed::newestFirst ------------------------------------------------------------------
// What    : The remembered games, newest first.
// Returns : the game ids
// Used by : doRecent (screens.h), tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    std::vector<int> newestFirst() const {
        std::vector<int> out;
        int id;
        for (int i = items.size() - 1; i >= 0; i--) {
            if (items.at(i, id)) out.push_back(id);
        }
        return out;
    }

//--- RecentlyViewed::size -------------------------------------------------------------------------
// What    : How many games are remembered.
// Returns : the count
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    int size() const { return items.size(); }
};

// one cart action that can be undone: it was an ADD (undo removes) or a REMOVE (undo adds back)
struct CartAction {
    int gameId = 0;
    bool wasAdd = true;
};

class CartUndo {
private:
    LinkedStack<CartAction> actions;

public:
//--- CartUndo::record -----------------------------------------------------------------------------
// What    : Remembers one cart action (add or remove) on the undo stack.
// Used by : doAddToCart (store.h), doBundle (screens.h), doCart (store.h), tests
//           (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    void record(int gameId, bool wasAdd) { actions.push(CartAction{gameId, wasAdd}); }
//--- CartUndo::pop --------------------------------------------------------------------------------
// What    : Takes the last action back off the stack.
// Returns : false when there is nothing to undo
// Used by : doCart (store.h), tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    bool pop(CartAction& out) { return actions.pop(out); }
//--- CartUndo::empty ------------------------------------------------------------------------------
// What    : Tells if there is nothing to undo.
// Returns : true when empty
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    bool empty() const { return actions.empty(); }
//--- CartUndo::size -------------------------------------------------------------------------------
// What    : How many actions can be undone.
// Returns : the count
// Used by : tests (tests/test_tree_hist.cpp)
//--------------------------------------------------------------------------------------------------
    int size() const { return actions.size(); }
//--- CartUndo::clear ------------------------------------------------------------------------------
// What    : Forgets all recorded actions (logout, empty cart).
// Used by : doCart (store.h), doLogout (store.h)
//--------------------------------------------------------------------------------------------------
    void clear() { actions.clear(); }
};

#endif //STEAM_HISTORY_H
